// 1. Counting Semaphore: Limiting Concurrent Access (Resource Pool)

constexpr int MAX_CONN = 5;
std::counting_semaphore<MAX_CONN> connection_pool{MAX_CONN};

void use_resource() {
    connection_pool.acquire();
    // Access limited shared resource
    connection_pool.release();
}

// 2. Binary Semaphore: Signaling/Flow Coordination (Like a Condition Variable)

std::binary_semaphore setup_complete{0}; // Starts locked

void Setup_Worker() {
    // Phase 1: Heavy initialization...
    setup_complete.release(); // Signal the waiting thread
}

void Consumer_Worker() {
    setup_complete.acquire(); // Wait for release signal
    // Phase 2: Proceed only after setup
}
